import java.io.BufferedReader
import java.io.InputStreamReader

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val (a, ta) = reader.readLine().split(" ").map { it.toInt() }
    val (b, tb) = reader.readLine().split(" ").map { it.toInt() }
    val timeStr = reader.readLine()
    val (hh, mm) = timeStr.split(":").map { it.toInt() }
    val departureTime = hh * 60 + mm

    val arrivalTime = departureTime + ta

    var count = 0

    // Buses from B to A that depart before Simion arrives and arrive after Simion departs
    // Bus departs B at time t, arrives A at t + tb
    // Simion departs A at departureTime, arrives B at arrivalTime
    // We need buses where t < arrivalTime and t + tb > departureTime

    // Buses from B start at 05:00 (300 minutes) and end at 23:59 (1439 minutes)
    val startB = 300
    val endB = 1439

    // Calculate the earliest and latest departure times from B that could meet Simion
    val earliestDepartureB = departureTime - tb + 1 // t + tb > departureTime => t > departureTime - tb
    val latestDepartureB = arrivalTime - 1 // t < arrivalTime

    // Find all valid departure times from B within [startB, endB] and [earliestDepartureB, latestDepartureB]
    val firstValid = maxOf(startB, earliestDepartureB)
    val lastValid = minOf(endB, latestDepartureB)

    if (firstValid <= lastValid) {
        // Count buses departing from B in the range [firstValid, lastValid] with frequency b
        // First bus at 05:00, then every b minutes
        // Find the first bus >= firstValid
        val firstBus = if (firstValid <= startB) {
            startB
        } else {
            val diff = firstValid - startB
            val steps = (diff + b - 1) / b // Ceiling division
            startB + steps * b
        }

        // Find the last bus <= lastValid
        val lastBus = if (lastValid >= startB) {
            val diff = lastValid - startB
            val steps = diff / b // Floor division
            startB + steps * b
        } else {
            -1 // No valid bus
        }

        if (firstBus <= lastBus && firstBus >= startB && lastBus <= endB) {
            count = (lastBus - firstBus) / b + 1
        }
    }

    println(count)
}
