    // First bus at 05:00 (300 minutes), last at 23:59 (1439 minutes)
    // Bus departs at time t, arrives at A at t + tb
    // Simion departs A at simionStart, arrives B at simionEnd
    // A bus from B departing at t will be on the road during [t, t + tb]
    // They meet if their intervals overlap: t < simionEnd and t + tb > simionStart
    // So t must be in (simionStart - tb, simionEnd)

    val minT = simionStart - tb + 1
    val maxT = simionEnd - 1

    // Find first bus departure time >= minT and >= 300
    val firstPossible = maxOf(minT, 300)
    // Find last bus departure time <= maxT and <= 1439
    val lastPossible = minOf(maxT, 1439)

    if (firstPossible <= lastPossible) {
        // Buses depart every b minutes starting from 300
        // First bus >= firstPossible
        val firstBus = if (firstPossible <= 300) 300 else {
            val diff = firstPossible - 300
            val steps = (diff + b - 1) / b
            300 + steps * b
        }

        if (firstBus <= lastPossible) {
            val lastBus = 300 + ((lastPossible - 300) / b) * b
            if (lastBus >= firstBus) {
                count = (lastBus - firstBus) / b + 1
            }
        }
    }

